@startuml

class Resident {
  + name : string
  + street_address : string
  + phone_number : string
  + email : string
}

class PickupRequest {
  + street_address : string
  + description : string
  + requested_day : date
  + pickup_window : string
}

class Vehicle {
  + storage_space : float
}

class Route {
  + date : date
}

class VolunteerDriver {
  + available_days : string[]
}

class Item {
  + description : string
  + weight : float
  + dimensions : string
  + category : string
}

class DistributionCenter {
  + name : string
}

class FoodBank {
  + name : string
}

class Client {
  + home_address : string
  + needed_categories : string[]
}

class Article {
  + rfid_tag : string
  + description : string
  + category : string
}

class H2SEmployee {
  + name : string
}

Resident "1" -- "*" PickupRequest : schedules
PickupRequest "1" -- "*" Item : contains
Vehicle "1" -- "*" Route : follows
VolunteerDriver "1" -- "*" Route : drives
Route "1" -- "*" PickupRequest : includes
Route "1" -- "*" Item : collects
Item "1" -- "0..1" Article : becomes
DistributionCenter "1" -- "*" Article : receives
DistributionCenter "1" -- "*" H2SEmployee : employs
FoodBank "1" -- "*" Item : receives
Client "0..1" -- "*" Article : receives
H2SEmployee "1" -- "*" Article : examines
H2SEmployee "1" -- "*" Client : calls
VolunteerDriver "1" -- "*" Article : delivers

@enduml

